// Прод, только чтение: сырой HTML через request API; объявления — из sitemap.
import { test, expect } from '@playwright/test';
import { readSitemap, rawHtml, metas, canonicals, ORIGIN } from './ssr-seo.helpers';

test.describe('SSR и SEO публичных страниц — метаданные', () => {
  test('canonical и og:url объявления без utm/from при заходе с параметрами #b489db @desktop @prod-safe', async ({ request }) => {
    const sm = await readSitemap(request);
    expect(sm.listingIds.length, 'объявления в sitemap').toBeGreaterThan(0);
    const id = sm.listingIds[0];
    const clean = `${ORIGIN}/businessdetail?id=${id}`;

    const { status, html } = await rawHtml(request, `/businessdetail?id=${id}&utm_source=x&from=wa`);
    expect(status).toBe(200);
    expect(canonicals(html), 'canonical').toEqual([clean]);
    expect(metas(html, 'og:url'), 'og:url').toEqual([clean]);
  });

  test('/b/<код> — редирект на /businessdetail?id=<uuid>, canonical там чистый #b489db @desktop @prod-safe', async ({ request }) => {
    const sm = await readSitemap(request);
    const ids = sm.listingIds.slice(0, 10);
    expect(ids.length, 'объявления в sitemap').toBeGreaterThan(0);

    const errors: string[] = [];
    for (const id of ids) {
      const clean = `${ORIGIN}/businessdetail?id=${id}`;
      const res = await request.get(`/b/${id.slice(0, 8)}`, { maxRedirects: 0 });
      const location = res.headers()['location'];
      if (res.status() < 300 || res.status() > 399 || !location) {
        errors.push(`${id}: /b/ ответил ${res.status()} без редиректа`);
        continue;
      }
      const target = new URL(location, ORIGIN);
      if (target.pathname !== '/businessdetail' || target.searchParams.get('id') !== id) {
        errors.push(`${id}: редирект на ${target.href}`);
        continue;
      }
      const page = await rawHtml(request, target.pathname + target.search);
      const can = canonicals(page.html);
      if (page.status !== 200 || can.length !== 1 || can[0] !== clean) errors.push(`${id}: ${page.status}, canonical ${JSON.stringify(can)}`);
    }
    expect(errors, '/b/<код> → canonical').toEqual([]);
  });
});
